import{z as i,x as A,o as e,c as B,q as E,j as r,D as o,d as t,s as l,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"AdaRound","description":"","frontmatter":{"title":"AdaRound","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/adaround.md","filePath":"llm/adaround.md","lastUpdated":1791063341000}'),u={name:"llm/adaround.md"};function p(T,a,D,m,R,h){const d=A("Mermaid");return e(),B("div",null,[a[2]||(a[2]=E('<h1 id="adaround" tabindex="-1">AdaRound <a class="header-anchor" href="#adaround" aria-label="Permalink to &quot;AdaRound&quot;">​</a></h1><div class="epigraph"><p>最近邻舍入最小化的是权重误差；层输出误差的最优整数点往往在台阶的另一侧。AdaRound 在校准激活上把舍入当成可学习的二值决策。</p><footer>—— Nagel et al., Up or Down? Adaptive Rounding for Post-Training Quantization, ICML 2020</footer></div><p><a href="/llm/calibration-set">校准集</a> 给出层输入 \\(X\\)。本课在均匀格子上问：每个权重该向上还是向下取整。缺口是 RTN（round-to-nearest）对 \\(\\|W-\\hat W\\|\\) 最优，对 \\(\\|WX-\\hat W X\\|\\) 不必最优。<a href="/llm/gptq">GPTQ</a> 用二阶补偿改邻居权重；AdaRound 不改连续值补偿，而改 <strong>离散选择本身</strong>。后课 Hessian 感知会把两条线接到一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTN 给每个权重的舍入误差都是同一量级（半格以内），但若该方向的 \\(X\\) 能量小，输出不疼；反之，小权重落在高能量方向上，RTN 仍就近，输出很疼。校准 \\(X\\) 把「能量方向」读进来，舍入应偏向减小 \\(WX\\) 误差的那一侧。缺口就是承认：<strong>量化器的最近邻几何 ≠ 任务几何</strong>。没有 \\(X\\)，AdaRound 退回 RTN。<span class="marginnote">直觉类比：同样是 1 厘米的测量误差，量床单无所谓，量手表里的螺丝就是废品。RTN 对每个权重都&quot;就近距离&quot;，等于不看这个误差后面接的是床单还是螺丝；AdaRound 先看校准数据里哪条方向被放大得多，把舍入误差挪到&quot;无关紧要的床单&quot;那一边。</span></p><p><span class="marginnote">AdaRound 原论文面向视觉网络 PTQ。LLM 上同类思想出现在后续重建量化里。本课讲机制；大规模默认路径仍常是 GPTQ/AWQ，但舍入不必是最近邻这一课要先立住。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对已确定 \\(s\\) 的均匀量化，每个权重落在两个相邻整数之间。Nagel 等人把选择松弛成可学习变量，目标是校准上的层输出 MSE，加正则把松弛推回 0/1，逐层优化。不回传全网，仍是 PTQ；比纯 RTN 贵（每层要跑一轮小优化），比 QAT 便宜。<span class="marginnote">术语翻译：「PTQ（后训练量化）」就是模型已经训完、不再改训练流程，只拿一小批代表性数据（校准集）把权重压到低比特。与之相对的 QAT 是&quot;边训练边适应量化&quot;。AdaRound 属于前者：不重训，只是在&quot;每个权重向上还是向下&quot;这道二选一上做一小轮优化。</span></p><p>与 GPTQ 分工：AdaRound 假定格子已定，只动舍入；GPTQ 在列上取整并用 Hessian 改未量化列。可以先 AdaRound 再当初始化，或只在较小模型上用 AdaRound，175B 上 GPTQ 的块 Cholesky 更常见。不要把两者写成互斥教条。</p>',9)),(e(),r(s,null,{default:o(()=>[l(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22FP%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20GRID%5B%22%E5%B7%B2%E5%AE%9A%E5%9D%87%E5%8C%80%E6%A0%BC%E5%AD%90%22%5D%0A%20%20X%5B%22%E6%A0%A1%E5%87%86%20X%22%5D%20--%3E%20OBJ%5B%22%E5%B1%82%E8%BE%93%E5%87%BA%20MSE%22%5D%0A%20%20GRID%20--%3E%20REL%5B%22%E6%9D%BE%E5%BC%9B%E8%88%8D%E5%85%A5%E5%8F%98%E9%87%8F%22%5D%0A%20%20REL%20--%3E%20OBJ%0A%20%20OBJ%20--%3E%20BIN%5B%22%E6%94%B6%E6%95%9B%E5%88%B0%E4%B8%8A%E6%88%96%E4%B8%8B%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"局部目标 \\(\\min \\|\\hat W X - W X\\|_F^2\\) 对每个舍入位是组合问题。松弛 + 退火正则把它变成连续优化，局部极小对应一套一致的上/下模式。校准偏了，模式拟合错误 \\(X\\)，换域更差——比 RTN 更过拟合校准，因为自由度正好用在这批激活上。",-1)),(e(),r(s,null,{default:o(()=>[l(d,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E8%90%BD%E5%9C%A8%203.4%22%5D%20--%3E%20RTN%5B%22RTN%EF%BC%9A%E5%B0%B1%E8%BF%91%E5%8F%96%203%22%5D%0A%20%20W%20--%3E%20ADA%5B%22%E5%85%88%E7%9C%8B%E6%A0%A1%E5%87%86%20X%20%E7%9A%84%E8%83%BD%E9%87%8F%22%5D%0A%20%20ADA%20--%3E%20UP%5B%22%E5%8F%96%204%20%E8%BE%93%E5%87%BA%E8%AF%AF%E5%B7%AE%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20UP%20--%3E%20WIN%5B%22%E6%9D%83%E9%87%8D%E8%AF%AF%E5%B7%AE%E7%A8%8D%E5%A4%A7%EF%BC%8C%E8%BE%93%E5%87%BA%E6%9B%B4%E5%87%86%22%5D%0A%20%20RTN%20--%3E%20LOSS%5B%22%E6%9D%83%E9%87%8D%E8%BF%91%E4%BA%86%EF%BC%8C%E8%BE%93%E5%87%BA%E5%8F%AF%E8%83%BD%E6%9B%B4%E5%B7%AE%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p>计算：每层一次优化，内存要放 \\(W\\) 与 \\(X\\)。宽层、长校准会贵。分组量化时，舍入仍逐元素，尺度按组固定。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在没有校准的「即时量化」里谈 AdaRound。不要期望它解决离群绑架 \\(s\\) 的问题——\\(s\\) 错了，两侧台阶都远。先粒度与校准，再舍入。下一课用 Hessian 显式做二阶，GPTQ 是 LLM 规模的可用算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RTN 优权重 MSE；层输出 MSE 的最优舍入可以是另一侧。</li><li>AdaRound 在校准 \\(X\\) 上学习上/下，仍是逐层 PTQ。</li><li>比 RTN 更拟合校准域；集必须对。</li><li>与 GPTQ 补偿正交：一个改离散选择，一个改剩余连续权重。</li><li>出处：Nagel 等 ICML 2020 AdaRound。</li></ul>',5))])}const f=i(u,[["render",p]]);export{_ as __pageData,f as default};
